import inspect
from dataclasses import fields
from datetime import datetime
from decimal import Decimal

from ledger.models import Transaction
from ledger.netting import is_settled, net_balance

NOW = datetime(2024, 1, 1, 23, 59, 59)


def tx(tx_id, kind, amount, settled_at=datetime(2024, 1, 1, 12, 0)):
    return Transaction(tx_id, kind, Decimal(amount), settled_at=settled_at)


def test_settled_refund_reduces_balance():
    assert net_balance([tx("r1", "refund", "7.50")], NOW) == Decimal("-7.50")


def test_mixed_payments_and_refunds():
    txs = [tx("p1", "payment", "100"), tx("r1", "refund", "30"), tx("p2", "payment", "5.25")]
    assert net_balance(txs, NOW) == Decimal("75.25")


def test_refund_settled_exactly_at_close_is_subtracted():
    txs = [tx("p1", "payment", "10"), tx("r1", "refund", "4", settled_at=NOW)]
    assert net_balance(txs, NOW) == Decimal("6")


def test_payment_increases_balance():
    assert net_balance([tx("p1", "payment", "10")], NOW) == Decimal("10")


def test_unsettled_operations_are_ignored():
    txs = [tx("p1", "payment", "10", settled_at=None), tx("r1", "refund", "3", settled_at=datetime(2024, 1, 2, 0, 0))]
    assert net_balance(txs, NOW) == Decimal("0")


def test_empty_input_is_zero():
    assert net_balance([], NOW) == Decimal("0")


def test_public_signatures_unchanged():
    assert list(inspect.signature(net_balance).parameters) == ["transactions", "now"]
    assert list(inspect.signature(is_settled).parameters) == ["tx", "now"]


def test_transaction_dto_unchanged():
    assert [f.name for f in fields(Transaction)] == ["tx_id", "kind", "amount", "settled_at"]
